-- Brief state (#60): brief_state holds the lawyer-authored part of a listing's brief (prepared mark, carry edits, note) under FORCE RLS on app.workspace_id. app_brief_refresh_targets() lets the system sweep list the (workspace, listing) pairs to refresh (tomorrow's listings and listings with a confirmed next date within 7 days, India time) without a workspace scope: listing is under FORCE RLS; the function owner reads it through the owner_definer_read policy 0076 added (as 20261024120000 does for portfolio_case). Additive only.
CREATE TABLE "brief_state" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"listing_id" uuid NOT NULL,
	"prepared_by" uuid,
	"prepared_at" timestamp with time zone,
	"carry" jsonb DEFAULT '[]'::jsonb NOT NULL,
	"note" text,
	"updated_by" uuid,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	"workspace_id" uuid NOT NULL,
	CONSTRAINT "brief_state_workspace_listing_uq" UNIQUE("workspace_id","listing_id"),
	CONSTRAINT "brief_state_carry_chk" CHECK (jsonb_typeof("brief_state"."carry") = 'array')
);
