CREATE FUNCTION app_brief_refresh_targets()
  RETURNS TABLE (workspace_id uuid, listing_id uuid)
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp
  AS $$
    SELECT l.workspace_id, l.id FROM listing l
    JOIN organization o ON o.id = l.workspace_id
    WHERE o.deleted_at IS NULL
      AND (
        l.list_date = ((now() AT TIME ZONE 'Asia/Kolkata')::date + 1)
        OR (
          l.canonical AND l.confirmation_state = 'confirmed'
          AND l.list_date > (now() AT TIME ZONE 'Asia/Kolkata')::date
          AND l.list_date <= ((now() AT TIME ZONE 'Asia/Kolkata')::date + 7)
        )
      )
    ORDER BY l.workspace_id, l.id
  $$;--> statement-breakpoint
REVOKE ALL ON FUNCTION app_brief_refresh_targets() FROM PUBLIC;--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app_brief_refresh_targets() TO causedeck_app;
